import { NextResponse } from "next/server";
import { z } from "zod";
import { handle } from "@/lib/api";
import { normalizePairingCode, sha256 } from "@/lib/crypto";
import { prisma } from "@/lib/prisma";
import { registerDevice } from "@/lib/session";

const schema = z.object({ code: z.string().min(4).max(20), name: z.string().trim().min(1).max(60) });

/** Redeems a one-time pairing key generated by the household admin. */
export async function POST(req: Request) {
  return handle(async () => {
    const { code, name } = schema.parse(await req.json());
    const codeHash = sha256(normalizePairingCode(code));
    const pairing = await prisma.pairingCode.findUnique({ where: { codeHash } });
    // updateMany with usedAt: null makes redemption atomic — a code can only be used once.
    const claimed = pairing
      ? await prisma.pairingCode.updateMany({ where: { id: pairing.id, usedAt: null, expiresAt: { gt: new Date() } }, data: { usedAt: new Date() } })
      : { count: 0 };
    if (!pairing || !claimed.count) return NextResponse.json({ error: "That key is invalid or has expired" }, { status: 400 });
    await registerDevice(pairing.ownerId, name);
    return NextResponse.json({ ok: true });
  });
}
